INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mitbestimmungsgesetze nur für IT-Firmen gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für viele Branchen"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Mitbestimmungsgesetze in einer IT-Firma anwende?', 3, '[{"text": "Mitarbeiterbeteiligung", "correct": true, "because": "Kern der Gesetze"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Rechtliche Umsetzung zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gesetze gehören zu den Mitbestimmungsgesetzen?', 5, '[{"text": "Mitbestimmungsgesetz", "correct": true, "because": "Regelt Aufsichtsräte"}, {"text": "Drittelbeteiligungsgesetz", "correct": true, "because": "Für kleinere Firmen"}, {"text": "Büroverordnung", "correct": false, "because": "Kein Mitbestimmungsgesetz"}, {"text": "Farbgesetz", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mitbestimmungsgesetze regeln Arbeitnehmerrechte. b) Sie gelten nur für Firmen unter 500 Mitarbeitern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Über 500 Mitarbeiter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Mitbestimmungsgesetze in einer IT-Firma analysiere?', 4, '[{"text": "Betriebsgröße", "correct": false, "because": "Bestimmt Anwendung"}, {"text": "Aufsichtsrat", "correct": false, "because": "Regelungsziel"}, {"text": "Büroausstattung", "correct": true, "because": "Kein gesetzlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mitbestimmungsgesetze nur für Aktiengesellschaften gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch GmbHs etc."}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Mitbestimmungsgesetze?', 3, '[{"text": "Arbeitnehmerbeteiligung", "correct": true, "because": "Fördert Mitbestimmung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Rechtliche Struktur zählt"}, {"text": "Weniger Regeln", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Mitbestimmungsgesetze?', 5, '[{"text": "Paritätische Mitbestimmung", "correct": true, "because": "Gleiche Vertretung"}, {"text": "Schwellenwerte", "correct": true, "because": "Ab bestimmter Größe"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}, {"text": "Farbvorgaben", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Mitbestimmungsgesetze fördern Demokratie in Firmen. b) Sie sind immer freiwillig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verpflichtend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Mitbestimmungsgesetze in einer IT-Firma umzusetzen?', 4, '[{"text": "Mitarbeiteranzahl", "correct": false, "because": "Bestimmt Anwendung"}, {"text": "Aufsichtsrat", "correct": false, "because": "Regelungsziel"}, {"text": "Büroausstattung", "correct": true, "because": "Kein gesetzlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt das Mitbestimmungsgesetz ab 500 Mitarbeitern?', 2, '[{"text": "Nein", "correct": true, "because": "Ab 2000 Mitarbeiter"}, {"text": "Ja", "correct": false, "because": "Falscher Schwellenwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Mitbestimmungsgesetze?', 4, '[{"text": "Arbeitnehmerrechte", "correct": true, "because": "Fördern Mitbestimmung"}, {"text": "Transparenz", "correct": true, "because": "Einblick in Entscheidungen"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mitbestimmungsgesetze nur für Großunternehmen gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch mittlere Firmen ab 500"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Mitbestimmungsgesetze in einer IT-Firma zu analysieren?', 3, '[{"text": "Firmengröße", "correct": true, "because": "Bestimmt Anwendung"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Drittelbeteiligungsgesetz gilt ab 500 Mitarbeitern. b) Es regelt volle Parität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur Drittel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Mitbestimmungsgesetzen?', 5, '[{"text": "Schwellenwerte", "correct": true, "because": "Bestimmen Anwendung"}, {"text": "Aufsichtsrat", "correct": true, "because": "Regelungsziel"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbvorgaben", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Mitbestimmungsgesetze umsetze?', 3, '[{"text": "Mitarbeiterzahl", "correct": false, "because": "Bestimmt Anwendung"}, {"text": "Gesetzestext", "correct": false, "because": "Regelt Umsetzung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein gesetzlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Mitbestimmungsgesetze freiwillig?', 3, '[{"text": "Nein", "correct": true, "because": "Gesetzlich verpflichtend"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mitbestimmungsgesetze nur für deutsche Firmen gelten?', 2, '[{"text": "Ja", "correct": true, "because": "Deutsches Recht"}, {"text": "Nein", "correct": false, "because": "Nationales Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Mitbestimmungsgesetze?', 4, '[{"text": "Paritätische Vertretung", "correct": true, "because": "Kernprinzip"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Recht zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
